109	public:
110	  ContextManager<CPU> context_config;
111	
112	  Simulator(const sc_core::sc_module_name& name,
113	            std::span<uint8_t> ram_buffer = {},
114	            MemoryRegion ram_region = {RAM_BASE, RAM_END},
115	            MemoryRegion ram_alias_region = {RAM_ALIAS_BASE, RAM_ALIAS_END})
116	      : sc_core::sc_module{name},
117	        platform("platform", ram_buffer, ram_region, ram_alias_region),
118	        dtm(platform.dtm)
119	  {
120	    cpu.bind(platform.clk, platform.resetn, platform.reset_vector,
121	             platform.dmi_signals, platform.wfi_signal, platform.int_trigger);
122	
123	    // --- CPU memory BFM → interconnect ---
124	    if constexpr (is_axi) {
125	      mem_bridge = make_axi_to_tlm("mem_bridge", cpu.mem_bfm.isckt);
126	      platform.interconnect.bind_initiator(mem_bridge->tlm_isck);
127	    } else {
128	      platform.interconnect.bind_initiator(cpu.mem_bfm.isckt);
129	    }
130	
131	    // --- CPU MMIO BFM → interconnect ---
132	    if constexpr (requires { cpu.mmio_bfm; }) {
133	      if constexpr (is_axi) {
134	        mmio_bridge = make_axi_to_tlm("mmio_bridge", cpu.mmio_bfm.isckt);
135	        platform.interconnect.bind_initiator(mmio_bridge->tlm_isck);
136	      } else {
137	        platform.interconnect.bind_initiator(cpu.mmio_bfm.isckt);
138	      }
139	    }
140	
141	    // --- CPU HVM subordinate port ---
142	    if constexpr (requires { cpu.hvm_bfm; }) {
143	      if constexpr (is_axi) {
144	        hvm_bridge = make_tlm_to_axi("hvm_bridge", cpu.hvm_bfm.tsckt);
145	        platform.interconnect.bind_target(
146	          hvm_bridge->tlm_tsck,
147	          {CPU::NDS_HVM_BASE,
148	           CPU::NDS_HVM_BASE + CPU::NDS_HVM_SIZE_KB * 0x1000 - 1});
149	      } else {
150	        platform.interconnect.bind_target(
151	          cpu.hvm_bfm.tsckt,
152	          {CPU::NDS_HVM_BASE,
153	           CPU::NDS_HVM_BASE + CPU::NDS_HVM_SIZE_KB * 0x1000 - 1});
154	      }
155	      platform.custom_master.hvm_base = CPU::NDS_HVM_BASE;
156	    }
157	
158	    // --- CPU slave port ---
159	    if constexpr (requires { cpu.slv_bfm; }) {
160	      if constexpr (is_axi) {
161	        slv_bridge = make_tlm_to_axi("slv_bridge", cpu.slv_bfm.tsckt);
162	        platform.interconnect.bind_target(slv_bridge->tlm_tsck,
163	                                          {HART0_ILM_BASE, HART0_DLM_END});
164	      } else {
165	        platform.interconnect.bind_target(cpu.slv_bfm.tsckt,
166	                                          {HART0_ILM_BASE, HART0_DLM_END});
167	      }
168	      platform.custom_master.ilm_base = HART0_ILM_BASE;
169	      platform.custom_master.dlm_base = HART0_DLM_BASE;
170	    }
171	
172	    // --- CPU sys bus (slave port, 64-bit) → interconnect ---
173	    if constexpr (requires { cpu.sys_bfm; }) {
174	      sys_adapter =
175	        std::make_unique<socket_width_adapter<bus_width, sys_bus_width>>(
176	          "sys_adapter");
177	      sys_bridge =
178	        std::make_unique<tlm_to_axi_bridge<sys_bus_width>>("sys_bridge");
